import React, { useState, useEffect } from 'react';
import { getPartidos, getAsistenciaPartidos, toggleConvocarsePartido, getCurrentUser } from '../../database/db';
import './MisPartidos.css';

function MisPartidos() {
  const [partidos, setPartidos] = useState([]);
  const [convocatoria, setConvocatoria] = useState([]);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      const currentUser = getCurrentUser();
      setUser(currentUser);
      
      const [partidosData, convocatoriaData] = await Promise.all([
        getPartidos(),
        getAsistenciaPartidos()
      ]);
      
      setPartidos(partidosData);
      setConvocatoria(convocatoriaData);
    } catch (error) {
      console.error('Error cargando datos:', error);
      alert('Error al cargar los partidos');
    }
    setLoading(false);
  };

  const handleConvocarse = async (partidoId) => {
    try {
      await toggleConvocarsePartido(partidoId, user.Id);
      await cargarDatos();
      alert('✅ Estado actualizado');
    } catch (error) {
      alert('Error al actualizar: ' + error.message);
    }
  };

  const getMiEstado = (partidoId) => {
    const registro = convocatoria.find(c => c.PartidoId === partidoId && c.JugadorId === user?.Id);
    return registro?.Estado || 'no_convocado';
  };

  const getEstadoInfo = (estado) => {
    const estados = {
      'convocado': { text: '📋 Convocado', class: 'estado-convocado', accion: 'Cancelar' },
      'jugo': { text: '⚽ Jugaste', class: 'estado-jugo', accion: null },
      'falta': { text: '❌ No jugaste', class: 'estado-falta', accion: null },
      'no_convocado': { text: '⭕ No convocado', class: 'estado-no', accion: 'Convocarme' }
    };
    return estados[estado] || estados.no_convocado;
  };

  // Obtener valores con soporte para ambos formatos
  const getFecha = (part) => part.Fecha || part.fecha;
  const getHora = (part) => part.Hora || part.hora;
  const getLugar = (part) => part.Lugar || part.lugar;
  const getRival = (part) => part.Rival || part.rival;
  const getMontoPago = (part) => part.MontoPago || part.monto_pago;

  // Filtrar partidos
  const partidosFuturos = partidos.filter(p => new Date(getFecha(p)) >= new Date());
  const partidosPasados = partidos.filter(p => new Date(getFecha(p)) < new Date());

  if (loading) {
    return (
      <div className="mis-partidos">
        <div className="loading-container">Cargando partidos...</div>
      </div>
    );
  }

  return (
    <div className="mis-partidos">
      <h2><i className="fas fa-trophy"></i> Mis Partidos</h2>

      {/* Próximos partidos */}
      <div className="seccion-partidos">
        <h3><i className="fas fa-calendar-alt"></i> Próximos Partidos</h3>
        {partidosFuturos.length === 0 ? (
          <div className="empty-state">
            <i className="fas fa-calendar-check"></i>
            <p>No hay partidos programados próximamente</p>
          </div>
        ) : (
          <div className="partidos-grid">
            {partidosFuturos.map(part => {
              const estado = getMiEstado(part.Id);
              const estadoInfo = getEstadoInfo(estado);
              return (
                <div key={part.Id} className="partido-card-jugador">
                  <div className="rival-destacado">
                    <i className="fas fa-trophy"></i>
                    <h3>vs {getRival(part)}</h3>
                  </div>
                  <div className="info-partido">
                    <p><i className="fas fa-calendar"></i> {new Date(getFecha(part)).toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' })}</p>
                    <p><i className="fas fa-clock"></i> {getHora(part)} hrs</p>
                    <p><i className="fas fa-map-marker-alt"></i> {getLugar(part)}</p>
                    {getMontoPago(part) > 0 && <p className="monto"><i className="fas fa-dollar-sign"></i> Aporte: ${getMontoPago(part)}</p>}
                  </div>
                  <div className="accion-partido">
                    <span className={`estado-badge ${estadoInfo.class}`}>{estadoInfo.text}</span>
                    {estadoInfo.accion && (
                      <button onClick={() => handleConvocarse(part.Id)} className="btn-convocarse">
                        {estadoInfo.accion}
                      </button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Historial */}
      {partidosPasados.length > 0 && (
        <div className="seccion-partidos historial">
          <h3><i className="fas fa-history"></i> Historial de Partidos</h3>
          <div className="historial-grid">
            {partidosPasados.map(part => {
              const estado = getMiEstado(part.Id);
              const estadoInfo = getEstadoInfo(estado);
              return (
                <div key={part.Id} className="historial-card">
                  <div className="fecha-historial">
                    {new Date(getFecha(part)).toLocaleDateString()}
                  </div>
                  <div className="info-historial">
                    <span>vs {getRival(part)}</span>
                    <span className={`estado-small ${estadoInfo.class}`}>{estadoInfo.text}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

export default MisPartidos;
